local diff_utils = require("utils.diff")

local M = {}

---@class TocOptions
---@field mode? "github"|"gitlab" Default slugify mode ("github" or "gitlab", default "github")
---@field min? integer Minimum heading level to include (default 1)
---@field max? integer Maximum heading level to include (default 6)
---@field marker? string List bullet marker symbol without space (default "-")
---@field auto_update? boolean Automatically update TOC on buffer write and insert leave (default true)
---@field omit_toc? boolean Exclude "Table of Contents" / "TOC" headings (default true)

M.defaults = {
  mode = "github",
  min = 1,
  max = 6,
  marker = "-",
  auto_update = true,
  omit_toc = true,
}

M.config = vim.deepcopy(M.defaults)

--- Get indentation string based on buffer settings
---@param bufnr integer
---@return string
function M.get_buffer_indent(bufnr)
  bufnr = bufnr == 0 and vim.api.nvim_get_current_buf() or bufnr
  if not vim.bo[bufnr].expandtab then
    return "\t"
  end
  local sw = vim.bo[bufnr].shiftwidth
  if sw == 0 then
    sw = vim.bo[bufnr].tabstop
  end
  if sw == 0 then
    sw = 2
  end
  return string.rep(" ", sw)
end

--- Strip markdown inline formatting for slug generation
---@param text string
---@return string
function M.clean_inline(text)
  text = text:gsub("<[^>]+>", "")
  text = text:gsub("!%[[^%]]*%]%([^%)]*%)", "")
  text = text:gsub("%[([^%]]+)%]%([^%)]*%)", "%1")
  text = text:gsub("`([^`]+)`", "%1")
  text = text:gsub("%*%*(.-)%*%*", "%1"):gsub("%*(.-)%*", "%1")
  text = text:gsub("__(.-)__", "%1"):gsub("_(.-)_", "%1")
  text = text:gsub("~~(.-)~~", "%1")
  text = text:gsub("%s*#+%s*$", "")
  return text
end

--- Create visible link text safe for markdown `[text](#anchor)`
---@param raw string
---@return string
function M.create_link_text(raw)
  local text = raw
  text = text:gsub("<[^>]+>", "")
  text = text:gsub("!%[[^%]]*%]%([^%)]*%)", "")
  text = text:gsub("%[([^%]]+)%]%([^%)]*%)", "%1")
  text = text:gsub("%s*#+%s*$", "")
  text = vim.trim(text)
  -- Escape unescaped square brackets
  text = text:gsub("([^\\])%[", "%1\\["):gsub("^%[", "\\[")
  text = text:gsub("([^\\])%]", "%1\\]"):gsub("^%]", "\\]")
  return text
end

--- Generate anchor slug for heading text (GitHub and GitLab compatible)
---@param text string
---@param mode? "github"|"gitlab"
---@return string
function M.slugify(text, mode)
  mode = mode or M.config.mode or "github"
  local s = M.clean_inline(text)

  if mode == "gitlab" then
    s = vim.trim(s)
    s = s:gsub("%s*%*?%*?%([Cc]ore.-%)%*?%*?", "")
    s = s:gsub("%s*%*?%*?%([Ss]tarter.-%)%*?%*?", "")
    s = s:gsub("%s*%*?%*?%([Pp]remium.-%)%*?%*?", "")
    s = s:gsub("%s*%*?%*?%([Uu]ltimate.-%)%*?%*?", "")
  end

  -- Punctuation removal: strip ASCII punctuation (except - and _) and unicode punctuation
  local punct = [=[[!"#$%&'()*+,./:;<=>?@[\]^`{|}~“”‘’«»‹›—–…]]=]
  s = vim.fn.substitute(s, punct, "", "g")
  s = vim.fn.tolower(s)
  s = s:gsub(" ", "-")

  if mode == "gitlab" then
    s = s:gsub("%-+", "-")
    if s:match("^%d+$") then
      s = "anchor-" .. s
    end
  end

  return s
end

--- Stateful slug generator tracking duplicate occurrences (-1, -2, ...)
---@param mode? "github"|"gitlab"
---@return fun(text: string): string
function M.make_slug_generator(mode)
  local occurrences = {}
  return function(text)
    local slug = M.slugify(text, mode)
    local count = occurrences[slug]
    if not count then
      occurrences[slug] = 0
      return slug
    else
      count = count + 1
      occurrences[slug] = count
      return slug .. "-" .. count
    end
  end
end

--- Extract headings from buffer using Treesitter
---@param bufnr integer
---@return table[] List of { level: integer, text: string, line: integer }
function M.get_headings(bufnr)
  bufnr = bufnr == 0 and vim.api.nvim_get_current_buf() or bufnr
  local headings = {}

  local ok, parser = pcall(vim.treesitter.get_parser, bufnr, "markdown")
  if ok and parser then
    local tree = parser:parse()[1]
    if tree then
      local root = tree:root()
      local query = vim.treesitter.query.parse(
        "markdown",
        [[
        (atx_heading) @heading
        (setext_heading) @setext
      ]]
      )
      for _, node in query:iter_captures(root, bufnr) do
        local ntype = node:type()
        local srow = node:range()
        local level, text
        if ntype == "atx_heading" then
          for child in node:iter_children() do
            local ctype = child:type()
            local lvl = ctype:match("^atx_h(%d)_marker$")
            if lvl then
              level = tonumber(lvl)
            elseif ctype == "inline" then
              text = vim.treesitter.get_node_text(child, bufnr)
            end
          end
        elseif ntype == "setext_heading" then
          for child in node:iter_children() do
            local ctype = child:type()
            if ctype == "paragraph" then
              text = vim.treesitter.get_node_text(child, bufnr)
            elseif ctype == "setext_h1_underline" then
              level = 1
            elseif ctype == "setext_h2_underline" then
              level = 2
            end
          end
        end
        if level and text then
          text = vim.trim(text):gsub("%s*#+%s*$", "")
          table.insert(headings, { level = level, text = text, line = srow })
        end
      end
    end
  end

  -- Fallback if treesitter is unavailable
  if #headings == 0 then
    local lines = vim.api.nvim_buf_get_lines(bufnr, 0, -1, false)
    for i, line in ipairs(lines) do
      local hashes, title = line:match("^%s*(#{1,6})%s+(.-)%s*$")
      if hashes and title then
        title = title:gsub("%s*#+%s*$", "")
        table.insert(headings, { level = #hashes, text = title, line = i - 1 })
      end
    end
  end

  return headings
end

--- Generate TOC lines from headings
---@param bufnr integer
---@param headings table[]
---@param opts? TocOptions
---@return string[]
function M.generate_toc(bufnr, headings, opts)
  opts = vim.tbl_extend("force", M.config, opts or {})
  local mode = opts.mode or "github"
  local marker = vim.trim(opts.marker or M.config.marker or "-")
  local indent = opts.indent or M.get_buffer_indent(bufnr)
  local min_level = opts.min or opts.min_level or 1
  local max_level = opts.max or opts.max_level or 6
  local omit_toc = opts.omit_toc ~= nil and opts.omit_toc
    or (opts.omit_toc_heading ~= nil and opts.omit_toc_heading or true)

  local filtered = {}
  for _, h in ipairs(headings) do
    local is_toc_title = omit_toc
      and (
        h.text:lower():match("^table of contents$")
        or h.text:lower():match("^toc$")
        or h.text:lower():match("^contents$")
      )
    if not is_toc_title and h.level >= min_level and h.level <= max_level then
      table.insert(filtered, h)
    end
  end

  if #filtered == 0 then
    return {}
  end

  local min_h_level = 6
  for _, h in ipairs(filtered) do
    if h.level < min_h_level then
      min_h_level = h.level
    end
  end
  local start_depth = math.max(min_level, min_h_level)

  local slug_gen = M.make_slug_generator(mode)
  local lines = {}
  for _, h in ipairs(filtered) do
    local rel_level = math.max(0, h.level - start_depth)
    local slug = slug_gen(h.text)
    local visible = M.create_link_text(h.text)
    local line = string.rep(indent, rel_level) .. marker .. " [" .. visible .. "](#" .. slug .. ")"
    table.insert(lines, line)
  end

  return lines
end

--- Detect existing TOC in buffer and extract its settings (marker, indent, min, max, mode, omit_toc)
---@param bufnr integer
---@param headings table[]
---@param _? TocOptions
---@return table|nil { start_line: integer, end_line: integer, marker?: string, indent?: string, min?: integer, max?: integer, mode?: string, omit_toc?: boolean }
function M.find_existing_toc(bufnr, headings, _)
  bufnr = bufnr == 0 and vim.api.nvim_get_current_buf() or bufnr
  local ok, parser = pcall(vim.treesitter.get_parser, bufnr, "markdown")
  if not ok or not parser then
    return nil
  end

  local tree = parser:parse()[1]
  if not tree then
    return nil
  end
  local root = tree:root()

  -- Map valid slugs and titles from document headings
  local valid_slugs = {}
  local heading_texts = {}
  local gitlab_slug_matches = 0
  if headings then
    for _, h in ipairs(headings) do
      heading_texts[h.text:lower()] = true
      valid_slugs[M.slugify(h.text, "github")] = true
      valid_slugs[M.slugify(h.text, "gitlab")] = true
    end
  end

  local query = vim.treesitter.query.parse("markdown", "(list) @list")
  for _, node in query:iter_captures(root, bufnr) do
    local parent = node:parent()
    -- Only inspect top-level lists
    if not parent or parent:type() ~= "list_item" then
      local srow, _, erow, _ = node:range()
      -- Trim trailing blank lines
      while erow > srow do
        local l = vim.api.nvim_buf_get_lines(bufnr, erow - 1, erow, false)[1]
        if l and l:match("^%s*$") then
          erow = erow - 1
        else
          break
        end
      end

      local list_lines = vim.api.nvim_buf_get_lines(bufnr, srow, erow, false)
      local total_items = 0
      local matched_items = 0
      local matched_levels = {}
      local matched_heading_set = {}
      local detected_marker = nil
      local detected_indent = nil
      local prev_ind = nil
      local matched_toc_heading = false

      for _, l in ipairs(list_lines) do
        local ind, mark, text, anchor = l:match("^(%s*)([%-%*%+])%s+%[(.-)%]%(#([^%)]+)%)")
        if not mark then
          ind, mark, text, anchor = l:match("^(%s*)(%d+%.)%s+%[(.-)%]%(#([^%)]+)%)")
        end
        if mark and anchor then
          total_items = total_items + 1
          if not detected_marker then
            detected_marker = vim.trim(mark)
            prev_ind = ind
          elseif not detected_indent and prev_ind and #ind > #prev_ind then
            detected_indent = ind:sub(#prev_ind + 1)
          end

          if anchor:match("^anchor%-%d+$") then
            gitlab_slug_matches = gitlab_slug_matches + 1
          end

          -- Match against document headings to detect heading levels
          local matched_h = nil
          for _, h in ipairs(headings or {}) do
            local gh = M.slugify(h.text, "github")
            local gl = M.slugify(h.text, "gitlab")
            if anchor == gh or anchor == gl or text == M.create_link_text(h.text) or text:lower() == h.text:lower() then
              matched_h = h
              break
            end
          end

          if matched_h then
            matched_items = matched_items + 1
            matched_heading_set[matched_h] = true
            table.insert(matched_levels, matched_h.level)
            local clean_h = matched_h.text:lower()
            if clean_h:match("^table of contents$") or clean_h:match("^toc$") or clean_h:match("^contents$") then
              matched_toc_heading = true
            end
          end
        end
      end

      -- Check if list is preceded by a TOC heading
      local is_preceded_by_toc_heading = false
      if srow > 0 then
        for prev_idx = srow - 1, 0, -1 do
          local prev_line = vim.api.nvim_buf_get_lines(bufnr, prev_idx, prev_idx + 1, false)[1]
          if prev_line and not prev_line:match("^%s*$") then
            local clean_h = prev_line:gsub("^#+%s*", ""):gsub("%s*#+$", ""):lower()
            if clean_h:match("^table of contents") or clean_h:match("^toc$") or clean_h:match("^contents$") then
              is_preceded_by_toc_heading = true
            end
            break
          end
        end
      end

      if
        (total_items >= 1 and (matched_items / total_items) >= 0.5)
        or (is_preceded_by_toc_heading and total_items >= 1)
      then
        local detected_min = nil
        local detected_max = nil

        if #matched_levels > 0 then
          local min_in_toc = math.min(unpack(matched_levels))
          local max_in_toc = math.max(unpack(matched_levels))

          -- Check if document has headings shallower than min_in_toc that were omitted
          local has_shallower = false
          for _, h in ipairs(headings or {}) do
            local clean_h = h.text:lower()
            local is_toc_title = clean_h:match("^table of contents$")
              or clean_h:match("^toc$")
              or clean_h:match("^contents$")
            if not is_toc_title and h.level < min_in_toc and not matched_heading_set[h] then
              has_shallower = true
              break
            end
          end
          if has_shallower then
            detected_min = min_in_toc
          end

          -- Only constrain max if there are headings deeper than max_in_toc in the document,
          -- and all TOC items were matched (meaning no headings were in-flight being edited/renamed).
          local has_deeper = false
          local unmatched_toc_items = total_items - matched_items
          if unmatched_toc_items == 0 then
            for _, h in ipairs(headings or {}) do
              if h.level > max_in_toc and not matched_heading_set[h] then
                has_deeper = true
                break
              end
            end
          end

          if has_deeper then
            detected_max = max_in_toc
          end
        end

        local detected_omit_toc = nil
        if is_preceded_by_toc_heading then
          detected_omit_toc = not matched_toc_heading
        end

        local detected_mode = nil
        if gitlab_slug_matches > 0 then
          detected_mode = "gitlab"
        end

        return {
          start_line = srow,
          end_line = erow,
          marker = detected_marker,
          indent = detected_indent,
          min = detected_min,
          max = detected_max,
          mode = detected_mode,
          omit_toc = detected_omit_toc,
        }
      end
    end
  end

  return nil
end

--- Update existing Table of Contents in buffer, respecting existing settings
---@param bufnr? integer|table
---@param opts? table
---@return boolean Whether the TOC was updated
function M.update(bufnr, opts)
  if type(bufnr) == "table" and opts == nil then
    opts = bufnr
    bufnr = 0
  end
  bufnr = (bufnr == nil or bufnr == 0) and vim.api.nvim_get_current_buf() or bufnr
  opts = opts or {}

  local headings = M.get_headings(bufnr)
  local existing = M.find_existing_toc(bufnr, headings, opts)

  if not existing then
    if not opts.silent then
      vim.notify("No existing Table of Contents found in buffer", vim.log.levels.WARN)
    end
    return false
  end

  -- If leaving insert mode while cursor is inside the TOC itself, don't overwrite manual edits
  if opts.is_insert_leave then
    local cursor_row = vim.api.nvim_win_get_cursor(0)[1] - 1
    if cursor_row >= existing.start_line and cursor_row < existing.end_line then
      return false
    end
  end

  local buf_config = vim.b[bufnr].toc_config or {}

  -- Priority: explicit opts > buf_config > existing TOC detected settings > M.config defaults
  local mode = opts.mode or buf_config.mode or existing.mode or M.config.mode or "github"
  local min = opts.min or buf_config.min or existing.min or M.config.min or 1
  local max = opts.max or buf_config.max or existing.max or M.config.max or 6
  local marker = opts.marker or buf_config.marker or existing.marker or M.config.marker or "-"
  local indent = existing.indent or M.get_buffer_indent(bufnr)

  local omit_toc = opts.omit_toc
  if omit_toc == nil then
    omit_toc = buf_config.omit_toc
  end
  if omit_toc == nil then
    omit_toc = existing.omit_toc
  end
  if omit_toc == nil then
    omit_toc = M.config.omit_toc
  end

  -- Update buffer session config with any new explicit options
  if next(opts) ~= nil and not opts.silent then
    vim.b[bufnr].toc_config = vim.tbl_extend("force", buf_config, {
      mode = mode,
      min = min,
      max = max,
      marker = marker,
      omit_toc = omit_toc,
    })
  end

  local gen_opts = {
    mode = mode,
    min = min,
    max = max,
    marker = marker,
    indent = indent,
    omit_toc = omit_toc,
  }

  local new_lines = M.generate_toc(bufnr, headings, gen_opts)
  if #new_lines == 0 then
    return false
  end

  local old_lines = vim.api.nvim_buf_get_lines(bufnr, existing.start_line, existing.end_line, false)

  -- Check if lines actually changed
  local identical = (#old_lines == #new_lines)
  if identical then
    for i = 1, #old_lines do
      if old_lines[i] ~= new_lines[i] then
        identical = false
        break
      end
    end
  end

  if identical then
    return false
  end

  -- Preserve cursor & window viewport and apply minimal diff edits
  diff_utils.apply_diff(bufnr, existing.start_line, old_lines, new_lines, {
    join_undo = opts.join_undo,
    save_view = true,
  })

  if not opts.silent then
    vim.notify("Table of Contents updated", vim.log.levels.INFO)
  end
  return true
end

--- Insert TOC at cursor position or update if one already exists
---@param bufnr? integer|table
---@param opts? table
function M.insert(bufnr, opts)
  if type(bufnr) == "table" and opts == nil then
    opts = bufnr
    bufnr = 0
  end
  bufnr = (bufnr == nil or bufnr == 0) and vim.api.nvim_get_current_buf() or bufnr
  opts = opts or {}

  local headings = M.get_headings(bufnr)
  if #headings == 0 then
    vim.notify("No headings found to generate Table of Contents", vim.log.levels.WARN)
    return
  end

  local existing = M.find_existing_toc(bufnr, headings, opts)
  if existing then
    M.update(bufnr, opts)
    return
  end

  -- Save specified options in buffer-local configuration
  if next(opts) ~= nil then
    vim.b[bufnr].toc_config = vim.tbl_extend("force", vim.b[bufnr].toc_config or {}, opts)
  end

  local buf_config = vim.b[bufnr].toc_config or {}
  local mode = opts.mode or buf_config.mode or M.config.mode or "github"
  local min = opts.min or buf_config.min or M.config.min or 1
  local max = opts.max or buf_config.max or M.config.max or 6
  local marker = opts.marker or buf_config.marker or M.config.marker or "-"
  local indent = M.get_buffer_indent(bufnr)
  local omit_toc = opts.omit_toc
  if omit_toc == nil then
    omit_toc = buf_config.omit_toc
  end
  if omit_toc == nil then
    omit_toc = M.config.omit_toc
  end

  local gen_opts = {
    mode = mode,
    min = min,
    max = max,
    marker = marker,
    indent = indent,
    omit_toc = omit_toc,
  }

  local new_lines = M.generate_toc(bufnr, headings, gen_opts)
  if #new_lines == 0 then
    vim.notify("No matching headings found for Table of Contents", vim.log.levels.WARN)
    return
  end

  local cursor = vim.api.nvim_win_get_cursor(0)
  local row = cursor[1] - 1
  local cur_line = vim.api.nvim_buf_get_lines(bufnr, row, row + 1, false)[1] or ""

  -- If cursor is on a TOC heading, insert below it
  local lower = cur_line:lower()
  if lower:match("^#+%s*table of contents") or lower:match("^#+%s*toc$") or lower:match("^#+%s*contents$") then
    row = row + 1
    table.insert(new_lines, 1, "")
    table.insert(new_lines, "")
    diff_utils.insert_lines(bufnr, row, new_lines)
  elseif cur_line == "" then
    table.insert(new_lines, "")
    diff_utils.replace_lines(bufnr, row, row + 1, new_lines)
  else
    table.insert(new_lines, "")
    diff_utils.insert_lines(bufnr, row, new_lines)
  end

  vim.notify("Table of Contents generated", vim.log.levels.INFO)
end

--- Delete existing Table of Contents in buffer
---@param bufnr? integer|table
---@param opts? table
---@return boolean Whether the TOC was deleted
function M.delete(bufnr, opts)
  if type(bufnr) == "table" and opts == nil then
    opts = bufnr
    bufnr = 0
  end
  bufnr = (bufnr == nil or bufnr == 0) and vim.api.nvim_get_current_buf() or bufnr
  opts = opts or {}

  local headings = M.get_headings(bufnr)
  local existing = M.find_existing_toc(bufnr, headings, opts)

  if not existing then
    if not opts.silent then
      vim.notify("No Table of Contents found in buffer", vim.log.levels.WARN)
    end
    return false
  end

  local srow = existing.start_line
  local erow = existing.end_line

  -- If followed by an empty line, delete that too so spacing remains clean
  local total_lines = vim.api.nvim_buf_line_count(bufnr)
  if erow < total_lines then
    local next_line = vim.api.nvim_buf_get_lines(bufnr, erow, erow + 1, false)[1]
    if next_line and next_line:match("^%s*$") then
      erow = erow + 1
    end
  end

  diff_utils.replace_lines(bufnr, srow, erow, {}, { save_view = true })

  if not opts.silent then
    vim.notify("Table of Contents deleted", vim.log.levels.INFO)
  end
  return true
end

-- Alias for insert
M.create = M.insert

--- Parse command arguments into action and option dictionary
--- Supports subcommands: `insert`, `update`, `delete`
--- Supports key=value options: `mode=`, `min=`, `max=`, `marker=`, `omit_toc=`
---@param args_str string
---@return string action ("insert"|"update"|"delete")
---@return table options
function M.parse_args(args_str)
  local action = nil
  local opts = {}
  local subcommands = { insert = true, update = true, delete = true }

  for token in args_str:gmatch("%S+") do
    if not action and subcommands[token:lower()] then
      action = token:lower()
    else
      local key, val = token:match("^(%w+)%=(.*)$")
      if key and val then
        key = key:lower()
        if key == "mode" then
          opts.mode = val:lower()
        elseif key == "min" then
          opts.min = tonumber(val)
        elseif key == "max" then
          opts.max = tonumber(val)
        elseif key == "marker" then
          opts.marker = vim.trim(val)
        elseif key == "omit_toc" then
          opts.omit_toc = (val:lower() ~= "false")
        end
      elseif token:lower() == "github" or token:lower() == "gitlab" then
        opts.mode = token:lower()
      end
    end
  end

  return action or "insert", opts
end

--- Autocompletion handler for :Toc command
---@param arg_lead string
---@param cmd_line string
---@param _ integer
---@return string[]
function M.complete(arg_lead, cmd_line, _)
  local subcommands = { "insert", "update", "delete" }
  local option_prefixes = {
    "mode=",
    "min=",
    "max=",
    "marker=",
    "omit_toc=",
  }

  if arg_lead:match("^mode=") then
    return vim.tbl_filter(function(c)
      return vim.startswith(c, arg_lead)
    end, { "mode=github", "mode=gitlab" })
  elseif arg_lead:match("^min=") then
    return vim.tbl_filter(function(c)
      return vim.startswith(c, arg_lead)
    end, { "min=1", "min=2", "min=3", "min=4", "min=5", "min=6" })
  elseif arg_lead:match("^max=") then
    return vim.tbl_filter(function(c)
      return vim.startswith(c, arg_lead)
    end, { "max=1", "max=2", "max=3", "max=4", "max=5", "max=6" })
  elseif arg_lead:match("^marker=") then
    return vim.tbl_filter(function(c)
      return vim.startswith(c, arg_lead)
    end, { "marker=-", "marker=*", "marker=+" })
  elseif arg_lead:match("^omit_toc=") then
    return vim.tbl_filter(function(c)
      return vim.startswith(c, arg_lead)
    end, { "omit_toc=true", "omit_toc=false" })
  end

  local candidates = {}
  local words = vim.split(vim.trim(cmd_line), "%s+")
  local has_subcommand = false
  for i = 2, #words - 1 do
    if vim.tbl_contains(subcommands, words[i]:lower()) then
      has_subcommand = true
      break
    end
  end

  if not has_subcommand and #words <= 2 then
    vim.list_extend(candidates, subcommands)
  end
  vim.list_extend(candidates, option_prefixes)

  return vim.tbl_filter(function(c)
    return vim.startswith(c, arg_lead)
  end, candidates)
end

--- Setup TOC options, user commands, and autocommands
---@param opts? TocOptions
function M.setup(opts)
  M.config = vim.tbl_extend("force", M.defaults, opts or {})

  -- Register unified :Toc command with subcommands and options
  vim.api.nvim_create_user_command("Toc", function(cmd_opts)
    local action, parsed_opts = M.parse_args(cmd_opts.args)
    if action == "delete" then
      M.delete(0, parsed_opts)
    elseif action == "update" then
      M.update(0, parsed_opts)
    else
      M.insert(0, parsed_opts)
    end
  end, {
    nargs = "*",
    complete = M.complete,
    desc = "Markdown Table of Contents (insert, update, delete)",
  })

  -- Autocommand for auto-updating TOC on buffer save and insert leave
  if M.config.auto_update then
    local augroup = vim.api.nvim_create_augroup("markdown_toc_autoupdate", { clear = true })
    vim.api.nvim_create_autocmd({ "BufWritePre", "InsertLeave" }, {
      group = augroup,
      pattern = "*",
      callback = function(ev)
        if vim.bo[ev.buf].filetype == "markdown" then
          M.update(ev.buf, {
            silent = true,
            join_undo = true,
            is_insert_leave = (ev.event == "InsertLeave"),
          })
        end
      end,
      desc = "Auto-update Table of Contents on save and insert leave",
    })
  end
end

return M
